private Table convertObjects(Iterator<JsonNode> iter, ReadOptions options) {
    // flatten each object inside the array
    StringBuilder result = new StringBuilder("[");
    boolean first = true;
    for (; iter.hasNext();) {
        JsonNode rowObj = iter.next();
        String flattenedRow = null;
